**Transition Logic:**

```rust
impl SessionState {
    fn transition(&mut self, event: &ToolCallEvent, patterns_matched: Vec<PatternMatch>) -> State {
        match self.current_state {
            State::Normal => {
                // Check if tool requires elevation
                if event.tool.is_privileged() {
                    self.current_state = State::Elevated;
                    self.metadata.privilege_level += 2;
                } else if !patterns_matched.is_empty() {
                    self.current_state = State::Suspicious;
                    self.metadata.suspicious_events += 1;
                }
            }

            State::Elevated => {
                // Return to normal after 5 minutes of safe behavior
                if Utc::now() - self.last_activity > Duration::minutes(5)
                    && self.metadata.suspicious_events == 0 {
                    self.current_state = State::Normal;
                    self.metadata.privilege_level = self.metadata.privilege_level.saturating_sub(1);
                }

                // Escalate if suspicious pattern while elevated
                if !patterns_matched.is_empty() {
                    self.current_state = State::Suspicious;
                    self.metadata.suspicious_events += 1;
                }
            }

            State::Suspicious => {
                // Block if another pattern matches (confirmation)
                if !patterns_matched.is_empty() {
                    self.current_state = State::Blocked;
                }

                // Return to elevated after 10 minutes of no issues
                if Utc::now() - self.last_activity > Duration::minutes(10)
                    && patterns_matched.is_empty() {
                    self.current_state = State::Elevated;
                    self.metadata.suspicious_events = self.metadata.suspicious_events.saturating_sub(1);
                }
            }

            State::Blocked => {
                // Requires manual intervention to unblock
                // (or admin-configured auto-unblock after 24h)
            }
        }

        self.current_state
    }
}
