**Pattern Matching:**

```rust
impl L4Scanner {
    fn check_patterns(&self, session: &SessionState, new_event: &ToolCallEvent) -> Vec<PatternMatch> {
        let mut matches = Vec::new();

        for pattern in &self.patterns {
            if self.pattern_matches(session, new_event, pattern) {
                matches.push(PatternMatch {
                    pattern: pattern.name.clone(),
                    severity: pattern.severity,
                    matched_events: self.get_matching_events(session, pattern),
                });
            }
        }

        matches
    }

    fn pattern_matches(&self, session: &SessionState, new_event: &ToolCallEvent, pattern: &BehaviorPattern) -> bool {
        // Get events within pattern window
        let cutoff = Utc::now() - pattern.window;
        let relevant_events: Vec<_> = session.history.iter()
            .filter(|e| e.timestamp > cutoff)
            .chain(std::iter::once(new_event))
            .collect();

        // Check if sequence matches
        self.matches_sequence(&relevant_events, &pattern.sequence)
    }

    fn matches_sequence(&self, events: &[&ToolCallEvent], sequence: &[PatternStep]) -> bool {
        let mut seq_idx = 0;

        for event in events {
            if seq_idx >= sequence.len() {
                return true;  // All steps matched
            }

            if self.step_matches(event, &sequence[seq_idx]) {
                seq_idx += 1;
            }
        }

        seq_idx >= sequence.len()
    }
}
