**Response by Severity:**

```rust
enum ResponseAction {
    Allow,
    Warn { notify: bool },
    RequireApproval { timeout: Duration },
    Block { reason: String },
}

impl L4Scanner {
    fn determine_response(&self, state: State, patterns: &[PatternMatch]) -> ResponseAction {
        match state {
            State::Normal => ResponseAction::Allow,

            State::Elevated => {
                ResponseAction::Warn { notify: false }
            }

            State::Suspicious => {
                if patterns.iter().any(|p| p.severity >= Severity::High) {
                    ResponseAction::RequireApproval {
                        timeout: Duration::minutes(5)
                    }
                } else {
                    ResponseAction::Warn { notify: true }
                }
            }

            State::Blocked => {
                ResponseAction::Block {
                    reason: format!(
                        "Session blocked due to suspicious behavior patterns: {:?}",
                        patterns.iter().map(|p| &p.pattern).collect::<Vec<_>>()
                    )
                }
            }
        }
    }
}
