struct PendingApproval {
    approval_id: Uuid,
    tool_call: ToolCall,
    pii_detected: Vec<PIIDetection>,
    created_at: DateTime<Utc>,
    user_id: String,
    telegram_message_id: i64,
    status: ApprovalStatus,
    response_channel: oneshot::Sender<ApprovalDecision>,
}

enum ApprovalStatus {
    Pending,
    Approved,
    Denied,
    TimedOut,
}

struct PIIApprovalSystem {
    pending: Arc<Mutex<HashMap<Uuid, PendingApproval>>>,
    telegram_bot: TelegramBot,
    approval_cache: Arc<Mutex<ApprovalCache>>,
}

impl PIIApprovalSystem {
    async fn request_approval(&self, tool_call: ToolCall, pii: Vec<PIIDetection>) -> Result<ApprovalDecision> {
        let approval_id = Uuid::new_v4();
        let (tx, rx) = oneshot::channel();

        // 1. Send Telegram message
        let message_id = self.send_telegram_approval(&approval_id, &tool_call, &pii).await?;

        // 2. Store pending approval
        let pending = PendingApproval {
            approval_id,
            tool_call: tool_call.clone(),
            pii_detected: pii.clone(),
            created_at: Utc::now(),
            user_id: tool_call.context.user_id.clone(),
            telegram_message_id: message_id,
            status: ApprovalStatus::Pending,
            response_channel: tx,
        };

        self.pending.lock().unwrap().insert(approval_id, pending);

        // 3. Wait for response with timeout
        match timeout(Duration::minutes(5), rx).await {
            Ok(Ok(decision)) => Ok(decision),
            Ok(Err(_)) => {
                // Channel closed without decision
                self.handle_timeout(approval_id).await;
                Err(ApprovalError::Timeout)
            }
            Err(_) => {
                // Timeout
                self.handle_timeout(approval_id).await;
                Err(ApprovalError::Timeout)
            }
        }
    }

    async fn handle_timeout(&self, approval_id: Uuid) {
        let mut pending = self.pending.lock().unwrap();
        if let Some(approval) = pending.get_mut(&approval_id) {
            approval.status = ApprovalStatus::TimedOut;

            // Update Telegram message
            self.telegram_bot.edit_message(
                approval.telegram_message_id,
                "⏱️ *Approval request timed out*\n\nThe tool call was automatically denied."
            ).await.ok();
        }
    }
}
