    preferences: HashMap<(String, String), ApprovalPreference>,
    // Key: (user_id, hash(tool_call)) -> CachedDecision
    decisions: LruCache<(String, String), CachedDecision>,
}

enum ApprovalPreference {
    AlwaysAllow,
    AlwaysDeny,
    AlwaysAsk,
}

struct CachedDecision {
    decision: ApprovalDecision,
    expires_at: DateTime<Utc>,
}

impl PIIApprovalSystem {
    async fn check_cache(&self, user_id: &str, tool_call: &ToolCall, pii: &[PIIDetection]) -> Option<ApprovalDecision> {
        let cache = self.approval_cache.lock().unwrap();

        // 1. Check preferences for PII types
        for p in pii {
            let key = (user_id.to_string(), p.pii_type.clone());
            if let Some(pref) = cache.preferences.get(&key) {
                match pref {
                    ApprovalPreference::AlwaysAllow => return Some(ApprovalDecision::Approved),
                    ApprovalPreference::AlwaysDeny => return Some(ApprovalDecision::Denied),
                    ApprovalPreference::AlwaysAsk => continue,
                }
            }
        }

        // 2. Check recent identical decisions (within 1 hour)
        let tool_call_hash = calculate_hash(tool_call);
        let cache_key = (user_id.to_string(), tool_call_hash);

        if let Some(cached) = cache.decisions.get(&cache_key) {
            if Utc::now() < cached.expires_at {
                return Some(cached.decision);
            }
        }

        None
    }

    async fn store_approval_preference(&self, user_id: &str, pii_types: Vec<String>, preference: ApprovalPreference) -> Result<()> {
        let mut cache = self.approval_cache.lock().unwrap();

        for pii_type in pii_types {
            let key = (user_id.to_string(), pii_type);
            cache.preferences.insert(key, preference);
        }

        // Persist to database
        self.db.execute(
            "INSERT OR REPLACE INTO approval_preferences (user_id, pii_type, preference) VALUES (?, ?, ?)",
            params![user_id, pii_types.join(","), preference.to_string()],
        )?;

        Ok(())
    }
}
